            ["Enter to send · Shift+Enter for a new line · Escape to stop"] = ("Intro para enviar · Mayús+Intro para una nueva línea · Esc para detener", "Enter untuk mengirim · Shift+Enter untuk baris baru · Escape untuk berhenti", "Enter 发送 · Shift+Enter 换行 · Esc 停止"),
            ["Attach images, videos, PDFs and documents · or drop files / paste an image"] = ("Adjunta imágenes, vídeos, PDF y documentos · o arrastra archivos / pega una imagen", "Lampirkan gambar, video, PDF, dan dokumen · atau seret berkas / tempel gambar", "附加图片、视频、PDF 和文档 · 或拖放文件 / 粘贴图片"),
            ["Update ready to install"] = ("Actualización lista para instalar", "Pembaruan siap dipasang", "更新已就绪，可安装"),
            ["Open Settings > Application to install and restart when ready."] = ("Abre Ajustes > Aplicación para instalar y reiniciar cuando estés listo.", "Buka Pengaturan > Aplikasi untuk memasang dan memulai ulang saat siap.", "打开“设置 > 应用”进行安装，准备好后重启。"),
            ["Available:"] = ("Disponible:", "Tersedia:", "可用版本："),
            ["Installed:"] = ("Instalado:", "Terpasang:", "已安装："),
            ["Download updates automatically"] = ("Descargar actualizaciones automáticamente", "Unduh pembaruan otomatis", "自动下载更新"),
            ["Check for a release, download it, then choose when to install and restart."] = ("Busca una versión, descárgala y elige cuándo instalar y reiniciar.", "Periksa rilis, unduh, lalu pilih kapan memasang dan memulai ulang.", "检查新版本并下载，再自行选择何时安装和重启。"),
            ["Check once at normal startup when the last attempt was at least 24 hours ago."] = ("Comprueba al iniciar si han pasado al menos 24 horas desde el último intento.", "Periksa saat mulai jika upaya terakhir setidaknya 24 jam yang lalu.", "正常启动时，若距上次检查已超过 24 小时则检查一次。"),
            ["Automatic downloads are optional and may use a metered connection. They follow automatic startup checks; installation always waits for you."] = ("Las descargas automáticas son opcionales y pueden usar una conexión medida. Siguen las comprobaciones al inicio; la instalación siempre espera tu decisión.", "Unduhan otomatis opsional dan dapat memakai koneksi berbayar. Unduhan mengikuti pemeriksaan saat mulai; pemasangan selalu menunggu Anda.", "自动下载为可选项，可能使用按流量计费的网络。它跟随启动时的自动检查；安装始终等你确认。"),
            ["Restore the previous app and its saved settings? Changes to settings and JSON profile data since that backup will be replaced. Local media files are kept."] = ("¿Restaurar la aplicación anterior y sus ajustes? Se reemplazarán los cambios de ajustes y perfiles JSON desde esa copia. Se conservarán los archivos multimedia locales.", "Pulihkan aplikasi sebelumnya dan pengaturan tersimpan? Perubahan pengaturan dan data profil JSON sejak cadangan akan diganti. Berkas media lokal dipertahankan.", "恢复上一个版本及其保存的设置？自该备份以来的设置和 JSON 配置数据更改将被替换。本地媒体文件会保留。"),
            ["Restore previous version"] = ("Restaurar versión anterior", "Pulihkan versi sebelumnya", "恢复上一版本"),
            ["Download the official setup for this app's architecture and verify its size, version and SHA-256."] = ("Descarga el instalador oficial para esta arquitectura y verifica su tamaño, versión y SHA-256.", "Unduh pemasang resmi untuk arsitektur aplikasi ini dan verifikasi ukuran, versi, serta SHA-256.", "下载与当前应用架构匹配的官方安装包，并验证其大小、版本和 SHA-256。"),
            ["Save, create a recovery copy, install the verified update and reopen NabyScape."] = ("Guarda, crea una copia de recuperación, instala la actualización verificada y vuelve a abrir NabyScape.", "Simpan, buat salinan pemulihan, pasang pembaruan terverifikasi, dan buka kembali NabyScape.", "保存并创建恢复副本，安装已验证的更新，然后重新打开 NabyScape。"),
            ["Downloads use official GitHub releases. SHA-256 checks integrity; unsigned checksums do not establish publisher identity. Windows security checks remain enabled."] = ("Las descargas usan versiones oficiales de GitHub. SHA-256 comprueba la integridad; las sumas sin firma no acreditan al editor. Los controles de seguridad de Windows siguen activos.", "Unduhan memakai rilis GitHub resmi. SHA-256 memeriksa integritas; checksum tanpa tanda tangan tidak membuktikan identitas penerbit. Pemeriksaan keamanan Windows tetap aktif.", "下载使用官方 GitHub 发布版。SHA-256 用于校验完整性；未签名的校验和不能证明发布者身份。Windows 安全检查保持启用。"),
            ["Checks run only when you request them. A chat check sends one short message and may use provider credits; Hermes processes it as an agent message. Setup never opens the microphone or downloads models automatically."] = ("Las comprobaciones se ejecutan solo cuando las solicitas. Comprobar el chat envía un mensaje breve y puede usar créditos; Hermes lo procesa como mensaje de agente. La configuración nunca abre el micrófono ni descarga modelos automáticamente.", "Pemeriksaan hanya berjalan saat diminta. Pemeriksaan obrolan mengirim satu pesan singkat dan dapat memakai kredit penyedia; Hermes memprosesnya sebagai pesan agen. Penyiapan tidak pernah membuka mikrofon atau mengunduh model otomatis.", "检查仅在您主动发起时运行。聊天检查会发送一条短消息，可能消耗服务商额度；Hermes 会将其作为代理消息处理。设置过程绝不会自动打开麦克风或下载模型。"),
        };
}
